// ============================================================================
// Print-in-Place Articulated Butterfly Model (FDM 3D Printable)
// ============================================================================
// Coordinate System:
//   X-axis : Torso longitudinal direction (+X = Head/Antennae, -X = Abdomen)
//   Y-axis : Wing span direction (+Y = Left Wing, -Y = Right Wing)
//   Z-axis : Vertical print direction (Z = 0 is flat on the build plate)
//
// Structure:
//   3 Rigid Bodies:
//     1. Fixed Torso (parts_1.stl): Head, eyes, antennae, thorax, abdomen,
//        and left/right captive double-conical pin joints with gothic-arch bridges.
//     2. Left Wing (parts_2.stl): 360-degree captive bore hub + forewing/hindwing
//        with raised venation texture and decorative cellular cutouts.
//     3. Right Wing (parts_3.stl): Mirror-symmetric right wing.
//
// Printing Parameters Target:
//   PLA, 0.4 mm nozzle, 0.2 mm layer height, no supports required.
//   Pin-to-bore single-side radial clearance: 0.50 mm (within 0.4 - 0.6 mm).
// ============================================================================

$fn = 80;

// ----------------------------
// Render / Export Control
// ----------------------------
// Options: "all", "torso", "left_wing", "right_wing"
part_select = "all";

// Wing rotation angles in degrees (Valid collision-free range: <= -30 to >= +30)
left_wing_angle  = 0;
right_wing_angle = 0;

// ----------------------------
// Core Joint Parameters (mm)
// ----------------------------
joint_x = 2.0;               // Joint axis X position
joint_y = 10.5;              // Joint axis |Y| position (Left = +10.5, Right = -10.5)

radial_clearance = 0.50;     // Single-side radial clearance (0.4 - 0.6 mm spec)
axial_clearance  = 0.68;     // Minimum vertical Z clearance in gothic arch

pin_shaft_r      = 3.00;     // Central cylindrical pin radius (D = 6.00 mm)
pin_flare_r      = 4.30;     // Bottom/top conical retention flare radius (D = 8.60 mm)
bore_shaft_r     = pin_shaft_r + radial_clearance; // 3.50 mm (D = 7.00 mm)
bore_flare_r     = pin_flare_r + radial_clearance; // 4.80 mm (D = 9.60 mm)

knuckle_outer_r  = 7.20;     // Outer radius of wing knuckle ring (D = 14.40 mm)
torso_clear_r    = knuckle_outer_r + radial_clearance; // 7.70 mm

// Z-height levels (aligned to 0.20 mm layer increments)
z_bed            = 0.00;
z_skirt_top      = 0.80;     // Vertical base skirt top
z_bot_cone_top   = 2.40;     // Bottom conical retention top (dZ = 1.60, dR = 1.30 -> 50.9 deg)
z_mid_cyl_top    = 6.00;     // Central cylindrical shaft top (height = 3.60 mm)
z_top_cone_top   = 7.60;     // Top conical retention top (dZ = 1.60, dR = 1.30 -> 50.9 deg)
z_knuckle_top    = 8.60;     // Top of wing knuckle roof (dZ = 1.00, slope = 51.3 deg)
z_arch_merge     = 9.80;     // Gothic arch merge height (dZ = 2.20, dR = 1.70 -> 52.3 deg)
z_bridge_top     = 12.60;    // Top of torso shoulder bridge & pin cap

// Wing thickness parameters
wing_base_h      = 3.00;     // Main wing membrane/frame thickness
wing_vein_h      = 4.20;     // Raised decorative vein & border height

// ============================================================================
// Helper Modules
// ============================================================================

// Smooth 2D polygon rounding via offset
module smooth_2d(r_round = 1.5) {
    offset(r = r_round)
    offset(r = -2 * r_round)
    offset(r = r_round)
        children();
}

// 2D capsule between two points with end radii r1, r2
module bar_2d(p1, p2, r1, r2 = -1) {
    r_end = (r2 < 0) ? r1 : r2;
    hull() {
        translate(p1) circle(r = r1);
        translate(p2) circle(r = r_end);
    }
}

// 3D tapered capsule segment flat on Z=0 with 45-deg beveled top
module sculpted_segment(p1, p2, r1, r2, h1, h2) {
    hull() {
        translate([p1[0], p1[1], 0])
            cylinder(r1 = r1, r2 = max(0.6, r1 - 0.35 * h1), h = h1);
        translate([p2[0], p2[1], 0])
            cylinder(r1 = r2, r2 = max(0.6, r2 - 0.35 * h2), h = h2);
    }
}

// ============================================================================
// Joint Profiles & Modules
// ============================================================================

// 360-degree Captive Pin (Part of Fixed Torso)
module captive_pin() {
    rotate_extrude(angle = 360) {
        polygon(points = [
            [0.00,         z_bed],
            [pin_flare_r,  z_bed],
            [pin_flare_r,  z_skirt_top],
            [pin_shaft_r,  z_bot_cone_top],
            [pin_shaft_r,  z_mid_cyl_top],
            [pin_flare_r,  z_top_cone_top],
            [pin_flare_r,  z_bridge_top - 0.80],
            [pin_flare_r - 0.80, z_bridge_top],
            [0.00,         z_bridge_top]
        ]);
    }
}

// Torso Gothic-Arch Bridge connecting the Captive Pin to the Thorax Shoulder
// Spans a 100-degree angular sector on the inner (torso-facing) side of the joint.
module torso_shoulder_arch(is_left = true) {
    start_ang = is_left ? -140 : 40;
    union() {
        rotate([0, 0, start_ang])
        rotate_extrude(angle = 100) {
            polygon(points = [
                // Start at outer shoulder wall on bed
                [torso_clear_r, z_bed],
                [joint_y,       z_bed],
                [joint_y,       z_bridge_top - 0.80],
                [joint_y - 0.80, z_bridge_top],
                // Across top of bridge to pin center
                [pin_flare_r - 0.80, z_bridge_top],
                [pin_flare_r,   z_bridge_top - 0.80],
                [pin_flare_r,   z_top_cone_top],
                // Gothic arch apex (52.3 deg self-supporting slopes from both sides)
                [6.00,          z_arch_merge],
                [torso_clear_r, z_top_cone_top]
            ]);
        }
        // Smooth transition fairing into the central thorax body
        hull() {
            translate([0, is_left ? -joint_y : joint_y, 0])
                cylinder(r1 = 5.2, r2 = 3.8, h = z_bridge_top);
            translate([0, is_left ? -8.5 : 8.5, 0])
                cylinder(r1 = 4.2, r2 = 3.0, h = z_bridge_top);
        }
    }
}

// Clearance cutout subtracted from the Torso around each joint before adding the Pin
module wing_knuckle_clearance_cutout() {
    rotate_extrude(angle = 360) {
        polygon(points = [
            [0.00,          z_bed - 0.1],
            [torso_clear_r, z_bed - 0.1],
            [torso_clear_r, z_top_cone_top],
            [6.00,          z_arch_merge],
            [pin_flare_r,   z_top_cone_top],
            [0.00,          z_top_cone_top]
        ]);
    }
    // Outer swing clearance outside the 100-deg bridge sector
    // Ensures nothing on the torso above z_top_cone_top blocks the wing root
    rotate_extrude(angle = 360) {
        polygon(points = [
            [pin_flare_r + 0.01, z_bed - 0.1],
            [torso_clear_r,      z_bed - 0.1],
            [torso_clear_r,      z_top_cone_top],
            [6.00,               z_arch_merge],
            [pin_flare_r + 0.01, z_top_cone_top]
        ]);
    }
}

// 360-degree Wing Knuckle Hub with Captive Double-Conical Bore (Part of Wing)
module wing_knuckle_solid() {
    rotate_extrude(angle = 360) {
        polygon(points = [
            [bore_flare_r,    z_bed],
            [knuckle_outer_r, z_bed],
            [knuckle_outer_r, z_top_cone_top],
            [6.40,            z_knuckle_top],
            [5.60,            z_knuckle_top],
            [bore_flare_r,    z_top_cone_top],
            [bore_shaft_r,    z_mid_cyl_top],
            [bore_shaft_r,    z_bot_cone_top],
            [bore_flare_r,    z_skirt_top]
        ]);
    }
}

// ============================================================================
// Part 1: Fixed Butterfly Torso (Head, Eyes, Antennae, Thorax, Abdomen, Pins)
// ============================================================================

module butterfly_torso() {
    union() {
        difference() {
