            [bore_flare_r,    z_top_cone_top - cone_z_clearance],
            [bore_shaft_r,    z_mid_cyl_top - cone_z_clearance],
            [bore_shaft_r,    z_bot_cone_top + cone_z_clearance],
            [bore_flare_r,    z_skirt_top + cone_z_clearance]
        ]);
    }
}

